begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name": "Breakthrough Dog Training", "category": "Pet Services", "city": "Service area only", "address": null, "phone": "(209) 420-8693", "website": "https://www.btdogtraining.com/", "source_url": "https://www.btdogtraining.com/dog-training-lathrop-ca", "duplicate_key": "btdogtraining.com", "areas": ["Lathrop", "Manteca"], "tags": ["dog training", "puppy training"], "description": "Advertises private, one-on-one dog training at home and in everyday settings, with Lathrop and Manteca explicitly named. Programs include puppy and obedience training. Call to confirm your address, suitability, session location, program scope, quote and dates. No public visitor office, ordinary boarding or holiday availability established.", "note": "First-party Lathrop training page checked November14,2026 with fresh HTTP200. Identity, public2094208693, advertised private/in-home dog and puppy training and explicit Lathrop/Manteca service cities checked. Surrounding Central Valley wording does not establish Mountain House/Tracy coverage. No independent credentials, methods, safety, behavior outcomes, review count/rating, free-evaluation availability or price confirmation. Site template copyright year is not freshness evidence. No photos/testimonials/review data reused and no form submitted. Source: https://www.btdogtraining.com/dog-training-lathrop-ca"}]'::jsonb) loop
 if exists(select 1 from public.businesses where lower(name)=lower(r->>'name') or website ilike '%'||(r->>'duplicate_key')||'%' or (r->>'phone' is not null and right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10))) then raise exception 'Duplicate requires individual review: %',r->>'name'; end if;
 insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values(r->>'name',r->>'category',r->>'city',r->>'address',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now()) returning id into bid;
 insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,r->>'source_url',array['identity','public contact route','website','advertised services','explicit service cities','service limits'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
 select to_jsonb(b) into applied from public.businesses b where id=bid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'Individually source-checked directory expansion; no seed publication',r->>'source_url');
end loop;end $curate$;
commit;
select b.id,b.name,b.city,b.verified_at,c.service_areas,c.service_tags,c.checked_at from public.businesses b join public.listing_checks c on c.business_id=b.id where b.website='https://www.btdogtraining.com/';
